-- Partner-owned pipelines and the country template library.
--
--  * pipelines remember where they came from: cloned_from (another pipeline) and template_code/template_version
--    (the library template they began as). Copies are independent; the link only lets head office and managers compare
--    "the same" pipeline across partners.
--  * pipeline_templates: starter pipelines per country. Reference data shared by every company in that country, changed
--    only by a migration (like ce_rule_packs). Using one copies it into the person's own place; nothing is shared live.

ALTER TABLE pipelines
  ADD COLUMN cloned_from      uuid REFERENCES pipelines(id) ON DELETE SET NULL,
  ADD COLUMN template_code    text,
  ADD COLUMN template_version int;

CREATE TABLE pipeline_templates (
  code        text PRIMARY KEY CHECK (code ~ '^[a-z0-9_]{2,40}$'),
  country     text NOT NULL CHECK (country IN ('CA', 'US')),
  version     int  NOT NULL DEFAULT 1 CHECK (version >= 1),
  name        text NOT NULL,
  name_fr     text NOT NULL,
  description text NOT NULL,
  description_fr text NOT NULL,
  sort        int  NOT NULL DEFAULT 100,
  stages      jsonb NOT NULL,   -- [{ en, fr, won, lost, req?: [fieldKey|value|closeDate|owner] }]
  fields      jsonb NOT NULL,   -- [{ key, en, fr, type, options?, required? }]
  active      boolean NOT NULL DEFAULT true
);
GRANT SELECT ON pipeline_templates TO app_runtime;

